-- Development edition explicitly authorized November 9, 2026.
-- Draft prices; optional CAC facts; no old edition or run is rewritten.
BEGIN;
DO $install$
DECLARE new_version uuid := 'cba0ec75-2dbf-d329-324c-c6bae6a374e2'; source_version uuid;
 p public.personas%rowtype; c jsonb; ch jsonb; f jsonb; sid uuid; pid uuid;
 eid uuid; new_choice uuid; cat uuid; n integer; amount numeric; fee numeric; due integer;
 payload jsonb := $library$[{"key":"D001","title":"Looking for work","category":"Employment & Adult Education","engine":"employment","intent":"ALL","description":"You need work, and money is tight. Look through the job postings and decide where to apply.","choices":[],"facts":[{"role":"general","text":"Finding work can take time while everyday expenses continue.","semantic_key":"context:D001","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Building skills can be one part of preparing for the search for work. In 2025, CAC reported 610 total students in Adult Education programs.","semantic_key":"7cb64039-5726-43da-8f15-fbf8b63e8f83","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D002","title":"An interview today","category":"Employment & Adult Education","engine":"employment","intent":"ALL","description":"Your interview is today. What will you wear?","choices":[],"facts":[{"role":"general","text":"An interview can bring hope and another expense when you need something to wear.","semantic_key":"context:D002","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Clothing can be an important part of looking professional. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift to receive essential clothing.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D003","title":"Back to the job search","category":"Employment & Adult Education","engine":"employment","intent":"ALL","description":"The interview did not lead to a job. You still need work. Where will you apply next?","choices":[],"facts":[{"role":"general","text":"People come back to the job search from different starting points. Some are looking after a job ends, while others are returning after time away from work or seeking their first job.","semantic_key":"employment:jobseekers_different_work_histories","copy_kind":"fact","source_url":"https://www.bls.gov/cps/definitions.htm"},{"role":"cac","text":"Career support connects with the effort of finding your next opportunity. In 2025, The Empowerment Center's Career Services helped 229 people.","semantic_key":"db12c137-fad7-4277-b4ca-6a203b344e38","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D004","title":"Another interview","category":"Employment & Adult Education","engine":"employment","intent":"ALL","description":"You have another interview today. What will you wear?","choices":[],"facts":[{"role":"general","text":"Another interview can mean more time spent traveling and preparing, while keeping other needs in view.","semantic_key":"context:D004","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"In 2025, the CAC reported 80 job placements, helping people support themselves financially.","semantic_key":"2675ebbd-e014-4506-a0fd-1130a9ffe692","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D005","title":"Time to file taxes","category":"Financial Literacy & Taxes","engine":"ordinary","intent":"ALL","description":"It is time to file your taxes. Will you handle the return yourself or get help preparing it?","choices":[{"key":"TRY","text":"Try my best","response":"You filed your taxes yourself. You received no refund and paid no preparation fee.","requires_cac":false,"amount":0,"upfront_cost":0},{"key":"PAID","text":"Pay someone to prepare taxes","response":"You paid the preparation fee and received a $1,000 refund.","requires_cac":false,"amount":901,"upfront_cost":99},{"key":"CAC","text":"Get free tax preparation through CAC's VITA program","response":"You filed your taxes through CAC's free VITA program and received a $1,000 refund.","requires_cac":true,"amount":1000,"upfront_cost":0}],"facts":[{"role":"general","text":"Filing a tax return can mean money back for eligible workers and families. The Earned Income Tax Credit can provide a refund to people with low or moderate earnings even when they owe no federal income tax.","semantic_key":"tax:eitc_refundable_credit_for_workers","copy_kind":"fact","source_url":"https://www.irs.gov/taxtopics/tc601"},{"role":"cac","text":"Tax preparation can connect households with money back at filing time. In 2025, CAC reported 503 tax returns through VITA and $672,056 in combined federal and state refunds.","semantic_key":"cac:D005","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D006","title":"Rent is due","category":"Housing & Utilities","engine":"bill","intent":"ALL","description":"Rent is due. Paying it will leave less money for groceries, transportation, and everything else.","choices":[],"facts":[{"role":"general","text":"When rent comes due, keeping a roof over your head can leave less for everything else.","semantic_key":"context:D006","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Keeping housing stable is at the heart of CAC eviction prevention. In 2025, CAC reported preventing evictions for 1,108 households.","semantic_key":"5fa2bac7-6016-4db8-b705-fc593f6b75ec","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D007","title":"Keeping the lights on","category":"Housing & Utilities","engine":"bill","intent":"ALL","description":"The electricity bill is due. Your household still needs groceries and transportation this month. Which obligation will you carry?","choices":[],"facts":[{"role":"general","text":"Keeping the lights on means making room for electricity in a crowded budget.","semantic_key":"context:D007","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Utilities and rent draw on the money needed to keep a home. In 2025, CAC reported preventing evictions for 1,108 households.","semantic_key":"5fa2bac7-6016-4db8-b705-fc593f6b75ec","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D008","title":"The water bill","category":"Housing & Utilities","engine":"bill","intent":"ALL","description":"A water and sewer bill arrives. It is smaller than rent, but paying every small bill still adds up.","choices":[],"facts":[{"role":"general","text":"A water bill is another essential expense competing for the money you have.","semantic_key":"context:D008","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Water and sewer costs share the household budget with rent and other essentials. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","semantic_key":"b697ae84-1fd2-4bae-83da-7a10c983ac24","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D009","title":"Staying connected","category":"Essential Goods & Clothing","engine":"bill","intent":"ALL","description":"Your phone plan renews today. Keeping it paid competes with the money you were trying to save for an emergency.","choices":[],"facts":[{"role":"general","text":"A phone connection can be part of keeping up with work, family and daily responsibilities.","semantic_key":"context:D009","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D010","title":"The internet bill","category":"Housing & Utilities","engine":"bill","intent":"ALL","description":"Your internet bill is due. You use the connection for applications and household tasks, but it does not replace the phone bill.","choices":[],"facts":[{"role":"general","text":"Internet access is part of everyday life for most adults. In a 2025 U.S. survey, 90% of adults said they used the internet every day.","semantic_key":"digital:adult_daily_internet_use","copy_kind":"fact","source_url":"https://www.pewresearch.org/short-reads/2026/01/08/internet-use-smartphone-ownership-digital-divides-in-u-s/"},{"role":"cac","text":"Home internet is another bill competing for the money needed to maintain a household. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","semantic_key":"b697ae84-1fd2-4bae-83da-7a10c983ac24","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D011","title":"Car insurance is due","category":"Financial Literacy & Taxes","engine":"bill","intent":"CAR","description":"A car insurance installment is due. Ignoring it preserves cash today while leaving a larger amount unpaid.","choices":[],"facts":[{"role":"general","text":"Car insurance is another cost of keeping a vehicle available.","semantic_key":"context:D011","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Deciding how to handle an insurance bill is part of managing financial demands. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D012","title":"A clinic bill arrives","category":"Essential Goods & Clothing","engine":"bill","intent":"ALL","description":"A bill from an earlier clinic visit comes due. The care already happened; ignoring the invoice will not undo the visit.","choices":[],"facts":[{"role":"general","text":"In the Federal Reserve's 2025 U.S. survey, adults with lower family incomes were more likely to have gone without medical care because they could not afford it.","semantic_key":"health:income_related_forgone_care","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-economic-hardships.htm"}]},{"key":"D013","title":"The childcare bill","category":"Childcare & Youth","engine":"bill","intent":"JORDAN","description":"Maya’s agreed childcare arrangement has an invoice due. Paying it uses money you had hoped to keep available for the rest of the month.","choices":[],"facts":[{"role":"general","text":"Childcare can be one of a family's largest expenses. In the Federal Reserve's 2025 U.S. survey, most families paying for both childcare and housing spent at least half as much on childcare as on rent or mortgage payments.","semantic_key":"care:childcare_cost_relative_to_housing","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-living-arrangements-care-work.htm"}]},{"key":"D014","title":"Maya's school meal balance","category":"Childcare & Youth","engine":"bill","intent":"JORDAN","description":"Maya's school meal account has a balance due. How will you handle the bill?","choices":[],"facts":[{"role":"general","text":"A school meal balance is another expense to cover while making sure Maya has food during the day.","semantic_key":"context:D014","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"In 2025, CAC reported $6,678.22 in in-kind value through Meals for Kids.","semantic_key":"cac:meals_for_kids:in_kind_value","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D015","title":"The repair bill","category":"Essential Goods & Clothing","engine":"bill","intent":"CAR","description":"A repair completed before the month has a bill due today. The car is already repaired; this choice is about the unpaid invoice.","choices":[],"facts":[{"role":"general","text":"A repair bill can keep taking up space in your budget after the car is back on the road.","semantic_key":"context:D015","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D016","title":"A pharmacy bill arrives","category":"Essential Goods & Clothing","engine":"bill","intent":"ALL","description":"A pharmacy account invoice for an earlier purchase is due. The medicine was already supplied.","choices":[],"facts":[{"role":"general","text":"Some U.S. adults reported going without prescription medicine because of its cost in the Federal Reserve's 2025 survey.","semantic_key":"health:prescription_cost_barrier","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-economic-hardships.htm"}]},{"key":"D017","title":"A repayment is due","category":"Financial Literacy & Taxes","engine":"bill","intent":"ALL","description":"A payment on your existing repayment agreement is due. Paying it leaves less money for your other needs.","choices":[],"facts":[{"role":"general","text":"A repayment coming due can narrow the choices you have for other expenses.","semantic_key":"context:D017","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Repayments are one of the commitments a household has to plan around. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D018","title":"The gas bill","category":"Housing & Utilities","engine":"bill","intent":"ALL","description":"Your household gas bill is due. Paying it will use some of the money you have set aside for other needs.","choices":[],"facts":[{"role":"general","text":"Some U.S. households reported keeping their homes at unhealthy temperatures because of energy costs in the 2024 Residential Energy Consumption Survey.","semantic_key":"energy:unhealthy_home_temperature","copy_kind":"fact","source_url":"https://www.eia.gov/consumption/residential/data/2024/hc/pdf/HC11.1_2024.pdf"},{"role":"cac","text":"A gas bill is part of the wider pressure of keeping a home running. In 2025, CAC reported preventing evictions for 1,108 households.","semantic_key":"5fa2bac7-6016-4db8-b705-fc593f6b75ec","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D019","title":"Rent or a cash cushion?","category":"Housing & Utilities","engine":"bill","intent":"ALL","description":"Rent is due just as you start to rebuild a cash buffer. Paying means giving up that buffer; ignoring creates a larger obligation.","choices":[],"facts":[{"role":"general","text":"Paying rent can mean giving up the cash you hoped to keep for an unexpected expense.","semantic_key":"context:D019","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Rent pressure connects with the housing instability CAC financial assistance addresses. In 2025, CAC reported $796,416.64 in total financial assistance to prevent homelessness.","semantic_key":"b697ae84-1fd2-4bae-83da-7a10c983ac24","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D020","title":"A medical bill remains","category":"Essential Goods & Clothing","engine":"bill","intent":"ALL","description":"A medical bill is due. You can pay it now or leave the balance unpaid.","choices":[],"facts":[{"role":"general","text":"An unpaid medical bill can remain part of the budget as new needs arrive.","semantic_key":"context:D020","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D021","title":"The car will not start","category":"Essential Goods & Clothing","engine":"ordinary","intent":"CAR","description":"The car will not start. The repair quote could use much of your remaining money, but you still need a way to get around.","choices":[{"key":"D021-REPAIR","text":"Pay for the repair","response":"You pay for the quoted repair and keep the car available.","requires_cac":false,"amount":-620,"upfront_cost":0},{"key":"D021-TRANSIT","text":"Leave the car parked and use MARTA","response":"You leave the car unrepaired and use MARTA. Unreliable arrival times and longer waits mean more planning and more time away from home.","requires_cac":false,"amount":-50,"upfront_cost":0}],"facts":[{"role":"general","text":"When the car will not start, repair costs compete with the cost of getting around another way.","semantic_key":"context:D021","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D022","title":"An unexpected dental expense","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"You have a painful dental problem. Treatment costs more than an assessment, and the assessment alone will not cover treatment.","choices":[{"key":"D022-TREAT","text":"Pay for the quoted treatment","response":"You paid for dental treatment.","requires_cac":false,"amount":-480,"upfront_cost":0},{"key":"D022-ASSESS","text":"Pay for an assessment only","response":"You paid for the assessment. Dental treatment has not been paid for.","requires_cac":false,"amount":-90,"upfront_cost":0}],"facts":[{"role":"general","text":"Dental care was the type of care U.S. adults most often reported skipping because of cost in the Federal Reserve's 2025 survey.","semantic_key":"health:dental_most_skipped_care","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-economic-hardships.htm"}]},{"key":"D023","title":"A broken phone","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"Your phone breaks while you are waiting for work and household messages. Replacing it costs much more than the monthly service bill.","choices":[{"key":"D023-REPLACE","text":"Buy a replacement handset","response":"You have a replacement phone and substantially less cash.","requires_cac":false,"amount":-240,"upfront_cost":0},{"key":"D023-REPAIR","text":"Pay for the repair","response":"You pay for a repair rather than a replacement.","requires_cac":false,"amount":-95,"upfront_cost":0},{"key":"D023-WAIT","text":"Go without the phone for now","response":"You kept the money, but you still do not have a working phone.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"A broken phone means weighing a repair against the cost of a replacement.","semantic_key":"context:D023","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D024","title":"A family emergency","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"Someone close to you has a family emergency out of town. You want to be there, but the trip would use money set aside for your own household.","choices":[{"key":"D024-TRAVEL","text":"Pay for the trip","response":"You commit the travel cost and choose to be present.","requires_cac":false,"amount":-360,"upfront_cost":0},{"key":"D024-REMOTE","text":"Stay home and support them remotely","response":"You preserve the money but cannot be there in person.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"In the Federal Reserve's 2025 U.S. survey, people provided unpaid care to relatives or friends who needed help because of illness, disability or aging.","semantic_key":"care:unpaid_adult_relative_support","copy_kind":"fact","source_url":"https://www.federalreserve.gov/publications/2026-economic-well-being-of-us-households-in-2025-living-arrangements-care-work.htm"}]},{"key":"D025","title":"Childcare falls through","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"The person who usually watches Maya after school is sick and cannot care for her for the next two school days. Your shifts end after school lets out, so you need another plan.","choices":[{"key":"D025-AGENCY","text":"Arrange three hours of after-school care on each of the two days","response":"You arranged after-school care for both days to cover the rest of your shifts.","requires_cac":false,"amount":-129.96,"upfront_cost":0},{"key":"D025-SHORT","text":"Arrange 90 minutes of care each day and agree on earlier shifts with your employer","response":"You arranged shorter after-school care for both days and agreed on earlier shifts with your employer.","requires_cac":false,"amount":-64.98,"upfront_cost":0}],"facts":[{"role":"general","text":"A Census Bureau study of U.S. households found that problems finding adequate childcare were accompanied by time away from work.","semantic_key":"care:disruption_work_absence","copy_kind":"fact","source_url":"https://www.census.gov/library/working-papers/2026/demo/sehsd-wp2026-08.html"}]},{"key":"D026","title":"Time for new tires","category":"Essential Goods & Clothing","engine":"ordinary","intent":"CAR","description":"Your car needs tires. A new set costs a large part of your available money. The shop also has a lower-cost set.","choices":[{"key":"D026-NEW","text":"Buy the new set","response":"You pay for the new set.","requires_cac":false,"amount":-520,"upfront_cost":0},{"key":"D026-LOWER","text":"Buy the lower-cost set","response":"You choose the lower-cost set and keep more money for other needs.","requires_cac":false,"amount":-310,"upfront_cost":0}],"facts":[{"role":"general","text":"New tires are another expense to weigh against keeping the car available.","semantic_key":"context:D026","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D027","title":"Broken glasses","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"Your glasses break. You can choose a standard replacement or a less expensive basic pair.","choices":[{"key":"D027-STANDARD","text":"Buy the standard replacement","response":"You pay for the standard replacement.","requires_cac":false,"amount":-290,"upfront_cost":0},{"key":"D027-BASIC","text":"Buy the basic replacement","response":"You choose the basic replacement and retain more cash.","requires_cac":false,"amount":-95,"upfront_cost":0},{"key":"D027-DEFER","text":"Delay replacement","response":"You did not buy new glasses. Your glasses still need replacing.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Replacing broken glasses means finding an option that meets your needs and fits your budget.","semantic_key":"context:D027","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D028","title":"A plumbing problem","category":"Housing & Utilities","engine":"ordinary","intent":"ALL","description":"There is a plumbing problem at home, and the repair is your responsibility. You can pay for the full repair or a temporary fix.","choices":[{"key":"D028-FIX","text":"Pay for the full quoted repair","response":"The quoted repair is paid.","requires_cac":false,"amount":-410,"upfront_cost":0},{"key":"D028-TEMP","text":"Pay for the temporary workaround","response":"You buy time with the workaround, but the repair need remains.","requires_cac":false,"amount":-75,"upfront_cost":0}],"facts":[{"role":"general","text":"A plumbing problem can bring an expense that was never part of your plan for the month.","semantic_key":"context:D028","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D029","title":"An unexpected appointment for Maya","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"Maya needs a care appointment you had not budgeted for. You can pay for the full appointment or an initial appointment that leaves some care to arrange.","choices":[{"key":"D029-FULL","text":"Pay for the full appointment","response":"You commit the full appointment cost.","requires_cac":false,"amount":-380,"upfront_cost":0},{"key":"D029-INITIAL","text":"Pay for the initial appointment","response":"You paid for the initial appointment. The remaining care has not been arranged.","requires_cac":false,"amount":-120,"upfront_cost":0}],"facts":[{"role":"general","text":"An unexpected appointment for Maya means finding money for care alongside other family needs.","semantic_key":"context:D029","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D030","title":"A broken laptop","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"Your laptop fails. A replacement is expensive, and a repair quote is cheaper but would keep the same older device.","choices":[{"key":"D030-REPLACE","text":"Buy the replacement","response":"You pay for a replacement device.","requires_cac":false,"amount":-450,"upfront_cost":0},{"key":"D030-REPAIR","text":"Pay for the repair","response":"You repair the existing device.","requires_cac":false,"amount":-180,"upfront_cost":0},{"key":"D030-DEFER","text":"Manage without it for now","response":"You keep the money and the laptop remains unavailable.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"A broken laptop means weighing the cost of restoring a tool you use against other expenses.","semantic_key":"context:D030","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D031","title":"The car needs a tow","category":"Essential Goods & Clothing","engine":"ordinary","intent":"CAR","description":"The car needs towing. You have quotes to take it to a repair shop or to a parking location. Neither quote includes repairs.","choices":[{"key":"D031-SHOP","text":"Tow it to the repair shop","response":"The towing charge is paid; repairs are not included.","requires_cac":false,"amount":-225,"upfront_cost":0},{"key":"D031-PARK","text":"Tow it to the parking location","response":"You pay less for the tow, and the car still needs attention.","requires_cac":false,"amount":-140,"upfront_cost":0}],"facts":[{"role":"general","text":"A tow is another cost to cover before the car can be repaired.","semantic_key":"context:D031","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D032","title":"A larger share to cover","category":"Housing & Utilities","engine":"ordinary","intent":"SOFIA","description":"You and your spouse need to make a household purchase, and your share is larger than expected. You can cover the full share or agree on a smaller contribution that leaves part of the purchase unfunded.","choices":[{"key":"D032-FULL","text":"Pay the larger share","response":"You cover the stated share from your own available balance.","requires_cac":false,"amount":-420,"upfront_cost":0},{"key":"D032-SMALL","text":"Pay the smaller agreed contribution","response":"You made the smaller contribution you agreed on. Part of the household purchase remains unfunded.","requires_cac":false,"amount":-180,"upfront_cost":0}],"facts":[{"role":"general","text":"Covering more of a shared purchase can leave less for your own needs.","semantic_key":"context:D032","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D033","title":"A damaged work item","category":"Essential Goods & Clothing","engine":"ordinary","intent":"EMPLOYED","description":"An item you need for work is damaged. You can replace it or pay to have it repaired.","choices":[{"key":"D033-REPLACE","text":"Buy the replacement","response":"You pay for the replacement.","requires_cac":false,"amount":-350,"upfront_cost":0},{"key":"D033-REPAIR","text":"Pay for the repair","response":"You repair the existing item and preserve more cash.","requires_cac":false,"amount":-145,"upfront_cost":0}],"facts":[{"role":"general","text":"A damaged work item can mean paying to replace equipment you rely on.","semantic_key":"context:D033","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D034","title":"A broken dresser","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"Your dresser breaks, leaving you without enough storage for your clothes. A complete replacement costs more than a basic option.","choices":[{"key":"D034-FULL","text":"Buy the complete replacement","response":"You spend more for the complete replacement.","requires_cac":false,"amount":-279.99,"upfront_cost":0},{"key":"D034-BASIC","text":"Buy the basic option","response":"You choose the basic option and keep more cash.","requires_cac":false,"amount":-165,"upfront_cost":0},{"key":"D034-DEFER","text":"Make do without replacing it this month","response":"You kept the money. Your dresser still needs replacing.","requires_cac":false,"amount":0,"upfront_cost":0},{"key":"D034-CAC","text":"Get a dresser through CAC Canopy Thrift assistance","response":"You received a dresser through CAC Canopy Thrift.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Replacing a broken dresser means choosing how much of your budget to spend on a household need.","semantic_key":"context:D034","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D035","title":"Groceries lost","category":"Food & Nutrition","engine":"ordinary","intent":"ALL","description":"A refrigerator failure spoils your groceries. Replacing the food means spending money on something you already bought.","choices":[{"key":"D035-FULL","text":"Replace the full basket","response":"You bought groceries to replace the food you lost.","requires_cac":false,"amount":-165,"upfront_cost":0},{"key":"D035-SMALL","text":"Buy only the immediate essentials","response":"You replace fewer items and leave the rest of the basket unfilled.","requires_cac":false,"amount":-65,"upfront_cost":0},{"key":"D035-CAC","text":"Get replacement groceries from the CAC Mini-Market","response":"You received replacement groceries from the CAC Mini-Market.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Losing groceries means paying again for food you had already planned to use.","semantic_key":"context:D035","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Replacing lost groceries brings the need for food back into the budget. In 2025, the CAC Mini-Market reported 1,160,328 pounds of food available.","semantic_key":"efaf231b-3db3-4c4d-b276-758006af8aab","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D036","title":"A full grocery basket?","category":"Food & Nutrition","engine":"ordinary","intent":"ALL","description":"You have a grocery list, but buying everything on it would leave little money for anything else.","choices":[{"key":"D036-FULL","text":"Buy the full basket","response":"You buy the full basket.","requires_cac":false,"amount":-95,"upfront_cost":0},{"key":"D036-SMALL","text":"Buy the smaller basket","response":"You spend less and leave some listed food unpurchased.","requires_cac":false,"amount":-50,"upfront_cost":0},{"key":"D036-CAC","text":"Get groceries from the CAC Mini-Market","response":"You received groceries from the CAC Mini-Market.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Food insecurity can mean eating a less varied diet even when a household is still getting enough food to avoid cutting meal sizes.","semantic_key":"food:reduced_diet_variety","copy_kind":"fact","source_url":"https://ers.usda.gov/topics/food-nutrition-assistance/food-security-in-the-us/measurement"},{"role":"cac","text":"Food support can be part of finding a way to fill the next grocery basket. In 2025, there were 36,521 visits to the CAC Mini-Market.","semantic_key":"94210a01-4766-46ad-beba-d7400c9fd31e","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D037","title":"Your ride to work falls through","category":"Employment & Adult Education","engine":"ordinary","intent":"EMPLOYED","description":"The ride you arranged to work is canceled. You can pay for a direct ride or use a cheaper route that takes longer.","choices":[{"key":"D037-RIDE","text":"Pay for the direct ride","response":"You pay more for the direct route.","requires_cac":false,"amount":-38,"upfront_cost":0},{"key":"D037-TRANSIT","text":"Take the transit route","response":"You pay less and commit more travel time.","requires_cac":false,"amount":-5,"upfront_cost":0}],"facts":[{"role":"general","text":"When your ride to work falls through, getting to your shift becomes another expense to solve.","semantic_key":"context:D037","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D038","title":"A load of laundry","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"Your clothes need washing. Washing and drying the full load costs more than washing a smaller load and air-drying it.","choices":[{"key":"D038-FULL","text":"Wash and dry the full load","response":"You washed and dried the full load.","requires_cac":false,"amount":-4,"upfront_cost":0},{"key":"D038-SMALL","text":"Wash the smaller load and air-dry it","response":"You spend less, wash fewer items, and handle drying yourself.","requires_cac":false,"amount":-2.5,"upfront_cost":0}],"facts":[{"role":"general","text":"Clean clothes take a place in the budget alongside food, transportation and bills.","semantic_key":"context:D038","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D039","title":"Maya's school trip","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"Maya brings home an optional school trip notice. The fee is modest compared with rent, but it is another claim on the same money.","choices":[{"key":"D039-PAY","text":"Pay for the trip","response":"You paid for Maya to go on the school trip.","requires_cac":false,"amount":-28,"upfront_cost":0},{"key":"D039-DECLINE","text":"Decline the optional trip","response":"You kept the money, and Maya did not go on the trip.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Admission fees can be one part of a school outing, alongside travel and other trip costs.","semantic_key":"context:D039","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D040","title":"Worn-out shoes","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"Your everyday shoes are wearing out. A new pair costs more than repairing the existing pair.","choices":[{"key":"D040-BUY","text":"Buy the replacement shoes","response":"You buy the new pair.","requires_cac":false,"amount":-70,"upfront_cost":0},{"key":"D040-REPAIR","text":"Repair your existing shoes","response":"You repair the current pair instead.","requires_cac":false,"amount":-25,"upfront_cost":0},{"key":"D040-CAC","text":"Get shoes using credits from CAC Canopy Thrift","response":"You used CAC Canopy Thrift credits to get shoes.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Worn-out shoes mean weighing replacement against making the current pair last.","semantic_key":"context:D040","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Finding shoes you can use is one way clothing needs enter the household budget. In 2025, CAC Canopy Thrift served 2,152 households.","semantic_key":"5d6bc795-8a41-49ca-862f-9aaf73405b49","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D041","title":"Too tired to cook?","category":"Food & Nutrition","engine":"ordinary","intent":"ALL","description":"You get home tired. Buying a prepared meal saves effort, but ingredients cost less and require cooking.","choices":[{"key":"D041-PREPARED","text":"Buy the prepared meal","response":"You pay more and avoid cooking this meal.","requires_cac":false,"amount":-24,"upfront_cost":0},{"key":"D041-COOK","text":"Buy ingredients and cook","response":"You spend less and commit the preparation time.","requires_cac":false,"amount":-10,"upfront_cost":0}],"facts":[{"role":"general","text":"In the 2025 U.S. time-use survey, women were more likely than men to spend part of their day preparing food and cleaning up afterward.","semantic_key":"time:cooking_gender_participation","copy_kind":"fact","source_url":"https://www.bls.gov/news.release/archives/atus_06252026.htm"},{"role":"cac","text":"Ingredients for a home-cooked meal are part of a household food budget. In 2025, the CAC Mini-Market served 2,995 households.","semantic_key":"ec44118c-3be1-46b1-9585-8f34d638bbd9","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D042","title":"School supplies for Maya","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"Maya needs supplies for an upcoming school activity. You can buy the complete set or just the immediate required items.","choices":[{"key":"D042-FULL","text":"Buy the full supply set","response":"You purchase the complete set.","requires_cac":false,"amount":-48,"upfront_cost":0},{"key":"D042-BASIC","text":"Buy only the immediate items","response":"You buy the smaller set and leave the other items unpurchased.","requires_cac":false,"amount":-22,"upfront_cost":0},{"key":"D042-CAC","text":"Get school supplies through Tools for School","response":"You received school supplies through Tools for School.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"School supplies create another shopping list when the household budget is already committed.","semantic_key":"context:D042","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"School supplies are the need at the center of Tools for School. In 2025, Tools for School served 1,090 children.","semantic_key":"c6a72bf1-47ac-4d53-9adc-8ad68dd120c4","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D043","title":"A family birthday","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"A family birthday is coming up. You want to acknowledge it while keeping enough money for necessities.","choices":[{"key":"D043-GIFT","text":"Buy the gift you planned","response":"You spend money on the planned gift.","requires_cac":false,"amount":-35,"upfront_cost":0},{"key":"D043-SMALL","text":"Choose a smaller gift","response":"You choose a less expensive gift.","requires_cac":false,"amount":-10,"upfront_cost":0},{"key":"D043-TIME","text":"Give your time instead","response":"You make no purchase and choose a nonfinancial gesture.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"A family birthday can mean balancing a gesture of care with money needed for essentials.","semantic_key":"context:D043","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D044","title":"Getting to an appointment","category":"Employment & Adult Education","engine":"ordinary","intent":"ALL","description":"You have a household appointment across town. A direct ride costs more, while the transit route takes longer.","choices":[{"key":"D044-DIRECT","text":"Pay for a direct ride","response":"You pay for the direct trip.","requires_cac":false,"amount":-32,"upfront_cost":0},{"key":"D044-TRANSIT","text":"Take the transit route","response":"You spend less and commit more travel time.","requires_cac":false,"amount":-5,"upfront_cost":0}],"facts":[{"role":"general","text":"Getting to an appointment can mean choosing between a higher fare and more time in transit.","semantic_key":"context:D044","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D045","title":"A coat for Maya","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"Cold weather is here, and Maya needs a coat. You can buy a new one or a less expensive secondhand coat.","choices":[{"key":"D045-NEW","text":"Buy the new coat","response":"You buy the new coat.","requires_cac":false,"amount":-60,"upfront_cost":0},{"key":"D045-USED","text":"Buy the secondhand coat","response":"You meet the coat need with the lower-cost option.","requires_cac":false,"amount":-24,"upfront_cost":0},{"key":"D045-CAC","text":"Get a coat for Maya through Coats for Kids","response":"You received a coat for Maya through Coats for Kids.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"A coat is one of the clothing needs to plan for as Maya grows.","semantic_key":"context:D045","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"A warm coat is the need at the center of Coats for Kids. In 2025, Coats for Kids served 623 children.","semantic_key":"e8473e58-6338-4855-93be-7608f27696ab","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D046","title":"Packing lunch or buying it?","category":"Food & Nutrition","engine":"ordinary","intent":"EMPLOYED","description":"You can prepare lunches ahead of time or buy them during workdays. One option takes more time now; the other costs more money.","choices":[{"key":"D046-PACK","text":"Buy ingredients and pack lunches","response":"You spend less and do the preparation.","requires_cac":false,"amount":-26,"upfront_cost":0},{"key":"D046-BUY","text":"Buy the workday lunches","response":"You save preparation time and spend more.","requires_cac":false,"amount":-55,"upfront_cost":0}],"facts":[{"role":"general","text":"Packing lunches means buying ingredients ahead of time.","semantic_key":"context:D046","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Packing lunches starts with having groceries available at home. In 2025, the CAC Mini-Market reported 1,140,047 pounds of donated food.","semantic_key":"f1e16055-cb30-4633-8ce2-89d834ec92d1","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D047","title":"A broken bag","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"The bag you use for everyday travel breaks. You can replace it or pay for a repair.","choices":[{"key":"D047-REPLACE","text":"Buy the replacement bag","response":"You buy a replacement.","requires_cac":false,"amount":-45,"upfront_cost":0},{"key":"D047-REPAIR","text":"Repair the existing bag","response":"You choose the repair.","requires_cac":false,"amount":-15,"upfront_cost":0}],"facts":[{"role":"general","text":"A replacement bag is one of the personal goods that can become an unexpected purchase.","semantic_key":"context:D047","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D048","title":"Meals for Maya","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"Maya needs meals during a Meals for Kids program period. You can buy prepared meals or ingredients to cook at home.","choices":[{"key":"D048-MEALS","text":"Buy the prepared meal allocation","response":"You pay for the prepared meals.","requires_cac":false,"amount":-42,"upfront_cost":0},{"key":"D048-COOK","text":"Buy ingredients and prepare the meals","response":"You spend less and commit preparation time.","requires_cac":false,"amount":-24,"upfront_cost":0},{"key":"D048-CAC","text":"Get meals for Maya through Meals for Kids","response":"You received meals for Maya through Meals for Kids.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Planning meals for Maya means covering food alongside the rest of the household budget.","semantic_key":"context:D048","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Meals for Kids connects with the need to plan food for Maya. In 2025, Meals for Kids served 1,097 children.","semantic_key":"9496c5fe-de45-4ce7-96a9-4d6ba7f2ac01","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D049","title":"A fee to access your money","category":"Financial Literacy & Taxes","engine":"ordinary","intent":"ALL","description":"You need to access your money. One option charges a fee; a slower option is free.","choices":[{"key":"D049-FEE","text":"Use the fee-charging access option","response":"You paid the fee to access your money sooner.","requires_cac":false,"amount":-9,"upfront_cost":0},{"key":"D049-FREE","text":"Use the free option","response":"You avoid the fee and accept the slower process.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"People without bank accounts have cited high or unpredictable fees and minimum balance requirements among their reasons for staying outside the banking system.","semantic_key":"banking:reported_access_barriers","copy_kind":"fact","source_url":"https://www.federalreserve.gov/newsevents/speech/barr20250715a.htm"},{"role":"cac","text":"Comparing a fee with a free alternative is part of making your money stretch. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D050","title":"Running low on essentials","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"You are running low on household hygiene supplies. Buying the larger pack costs more today, while the smaller pack leaves more cash available.","choices":[{"key":"D050-LARGE","text":"Buy the larger pack","response":"You buy more supplies now.","requires_cac":false,"amount":-32,"upfront_cost":0},{"key":"D050-SMALL","text":"Buy the smaller pack","response":"You keep more cash and buy fewer supplies.","requires_cac":false,"amount":-14,"upfront_cost":0}],"facts":[{"role":"general","text":"Running low on essentials means deciding how much you can buy with the cash available.","semantic_key":"context:D050","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D051","title":"A chance to learn","category":"Employment & Adult Education","engine":"ordinary","intent":"ALL","description":"There is a skills workshop you would like to attend. The fee would leave less money for other needs.","choices":[{"key":"D051-ATTEND","text":"Pay for and attend the workshop","response":"You paid the fee and attended the workshop.","requires_cac":false,"amount":-45,"upfront_cost":0},{"key":"D051-DECLINE","text":"Decline the workshop this month","response":"You keep the money and do not attend.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"A chance to learn can mean weighing an opportunity against an immediate expense.","semantic_key":"context:D051","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Taking time to build skills is part of the learning journey. In 2025, CAC reported 610 total students in Adult Education programs.","semantic_key":"7cb64039-5726-43da-8f15-fbf8b63e8f83","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D052","title":"Maya's birthday","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"Maya wants a birthday celebration. You can pay for the original plan or choose a smaller celebration at home.","choices":[{"key":"D052-PLAN","text":"Pay for the original plan","response":"You spend the money on the original celebration.","requires_cac":false,"amount":-80,"upfront_cost":0},{"key":"D052-HOME","text":"Choose the smaller home celebration","response":"You choose the less expensive celebration.","requires_cac":false,"amount":-20,"upfront_cost":0}],"facts":[{"role":"general","text":"Even a smaller birthday at home can mean finding money for a cake.","semantic_key":"context:D052","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D053","title":"A holiday meal","category":"Food & Nutrition","engine":"ordinary","intent":"ALL","description":"A holiday meal is approaching. You can buy the larger planned basket or a smaller one that costs less.","choices":[{"key":"D053-FULL","text":"Buy the planned holiday basket","response":"You purchase the planned meal ingredients.","requires_cac":false,"amount":-85,"upfront_cost":0},{"key":"D053-SMALL","text":"Choose the smaller holiday basket","response":"You spend less and prepare a smaller meal.","requires_cac":false,"amount":-38,"upfront_cost":0},{"key":"D053-CAC","text":"Get a holiday food basket through CAC","response":"You received a holiday food basket through CAC.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Turkey can be one of the ingredients to budget for when planning a holiday meal.","semantic_key":"context:D053","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Holiday food support connects with putting a seasonal meal on the table. In 2025, 984 households received Holiday Food Baskets.","semantic_key":"1eec83c9-41ca-4aef-be22-1e36289d9d95","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D054","title":"Clothes need replacing","category":"Essential Goods & Clothing","engine":"ordinary","intent":"ALL","description":"An everyday clothing item needs replacing. Buying it new costs more than buying it secondhand.","choices":[{"key":"D054-NEW","text":"Buy the new item","response":"You buy the new item.","requires_cac":false,"amount":-55,"upfront_cost":0},{"key":"D054-USED","text":"Buy the secondhand item","response":"You choose the lower-cost item.","requires_cac":false,"amount":-20,"upfront_cost":0},{"key":"D054-CAC","text":"Get clothing using credits from CAC Canopy Thrift","response":"You used CAC Canopy Thrift credits to get clothing.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Replacing worn clothing means balancing what you need now with money needed elsewhere.","semantic_key":"context:D054","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Clothing credits are one way CAC supports access to replacement clothing. In 2025, clients used $206,768.67 in credits at CAC Canopy Thrift.","semantic_key":"859b8cec-1e1c-4887-9f55-fd55f1bb349c","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D055","title":"Someone asks for help","category":"Financial Literacy & Taxes","engine":"ordinary","intent":"ALL","description":"Someone you care about asks for help with an unexpected expense. Helping them leaves less for your own household.","choices":[{"key":"D055-FULL","text":"Give the requested help","response":"You give the requested amount. It is not a loan or expected repayment.","requires_cac":false,"amount":-60,"upfront_cost":0},{"key":"D055-SMALL","text":"Give a smaller amount","response":"You help with a smaller contribution.","requires_cac":false,"amount":-20,"upfront_cost":0},{"key":"D055-DECLINE","text":"Explain that you cannot contribute money","response":"You keep the money and decline the financial request.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Helping someone else means deciding how much room is left in your own budget.","semantic_key":"context:D055","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Deciding what you can give means taking your own financial commitments into account. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D056","title":"A holiday gift for Maya","category":"Childcare & Youth","engine":"ordinary","intent":"JORDAN","description":"You are considering a holiday gift for Maya. The planned gift costs more than a modest alternative.","choices":[{"key":"D056-PLANNED","text":"Buy the planned gift","response":"You buy the planned gift.","requires_cac":false,"amount":-65,"upfront_cost":0},{"key":"D056-MODEST","text":"Buy the modest alternative","response":"You choose the less expensive gift.","requires_cac":false,"amount":-18,"upfront_cost":0},{"key":"D056-DECLINE","text":"Make no gift purchase this month","response":"You did not buy a holiday gift this month.","requires_cac":false,"amount":0,"upfront_cost":0},{"key":"D056-CAC","text":"Get a holiday gift for Maya through Hope for the Holidays","response":"You received a holiday gift for Maya through Hope for the Holidays.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"A holiday gift can be meaningful while still competing with everyday expenses.","semantic_key":"context:D056","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"},{"role":"cac","text":"Hope for the Holidays connects with the wish to include a child in seasonal gift giving. In 2025, Hope for the Holidays served 614 households.","semantic_key":"18b975be-96cb-49ec-901b-ccd04c6c6a5c","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D057","title":"A pass or a few fares?","category":"Employment & Adult Education","engine":"ordinary","intent":"ALL","description":"You need to get around. A transit pass costs more upfront than buying fares for the trips you need right now.","choices":[{"key":"D057-PASS","text":"Buy the pass","response":"You bought the transit pass.","requires_cac":false,"amount":-23.75,"upfront_cost":0},{"key":"D057-FARES","text":"Buy only the immediate fares","response":"You keep more cash now without pass coverage for later travel.","requires_cac":false,"amount":-10,"upfront_cost":0}],"facts":[{"role":"general","text":"Buying a transit pass means spending more now in exchange for coverage on later trips.","semantic_key":"context:D057","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D058","title":"Laundry supplies are running low","category":"Essential Goods & Clothing","engine":"ordinary","intent":"SOFIA","description":"You and your spouse need laundry supplies. A larger purchase costs more today; buying only the immediate amount keeps cash available.","choices":[{"key":"D058-LARGE","text":"Buy the larger quantity","response":"You bought the larger quantity of laundry supplies.","requires_cac":false,"amount":-28,"upfront_cost":0},{"key":"D058-SMALL","text":"Buy the immediate amount","response":"You buy less and keep more cash.","requires_cac":false,"amount":-12,"upfront_cost":0}],"facts":[{"role":"general","text":"Buying laundry supplies means balancing what you need now against the cost of a larger pack.","semantic_key":"context:D058","copy_kind":"context","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/scenario-data-sourcing.md"}]},{"key":"D059","title":"Time with a friend","category":"Financial Literacy & Taxes","engine":"ordinary","intent":"ALL","description":"You have an opportunity to spend time with a friend. The planned outing costs money; an agreed free alternative is available.","choices":[{"key":"D059-OUT","text":"Pay for the planned outing","response":"You choose the paid outing and its cost.","requires_cac":false,"amount":-25,"upfront_cost":0},{"key":"D059-FREE","text":"Choose the free alternative together","response":"You keep the money and choose the free plan.","requires_cac":false,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"Americans were less likely to spend time socializing or communicating on an average day in 2025 than in 2015, according to the U.S. time-use survey.","semantic_key":"social:less_daily_socializing","copy_kind":"fact","source_url":"https://www.bls.gov/news.release/archives/atus_06252026.htm"},{"role":"cac","text":"Finding room for a paid outing is one of the choices involved in managing a budget. In 2025, 218 students enrolled in Financial Literacy Classes.","semantic_key":"d32689c8-067a-4f59-aa48-2424384b7116","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]},{"key":"D060","title":"The groceries are running low","category":"Food & Nutrition","engine":"ordinary","intent":"ALL","description":"There are still days left in the month, and the household needs food. A full restock costs more than the smaller basket.","choices":[{"key":"D060-FULL","text":"Buy the full restock","response":"You purchase the full restock.","requires_cac":false,"amount":-90,"upfront_cost":0},{"key":"D060-SMALL","text":"Buy the smaller restock","response":"You buy less food and preserve more cash.","requires_cac":false,"amount":-45,"upfront_cost":0},{"key":"D060-CAC","text":"Get groceries from the CAC Mini-Market","response":"You received groceries from the CAC Mini-Market.","requires_cac":true,"amount":0,"upfront_cost":0}],"facts":[{"role":"general","text":"For U.S. households experiencing very low food security, disrupted meals and reduced food intake were usually occasional episodes rather than a constant condition, according to USDA's 2024 report.","semantic_key":"food:episodic_shortages","copy_kind":"fact","source_url":"https://ers.usda.gov/sites/default/files/_laserfiche/publications/113623/ERR-358.pdf"},{"role":"cac","text":"A late-month food need is another reason a household may turn to food support. In 2025, the CAC Mini-Market served 7,034 individuals.","semantic_key":"0a3f963a-b2c5-47d6-8b9d-e0d396da6a66","copy_kind":"fact","source_url":"https://github.com/mariannglasier/team6310/blob/content/scenario-cac-facts/docs/data/cac-service-facts-2025.json"}]}]$library$::jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM public.content_versions WHERE version_id=new_version) THEN RAISE EXCEPTION 'Library edition already exists; do not overwrite'; END IF;
 SELECT version_id INTO STRICT source_version FROM public.content_versions
 WHERE status='published' AND published_at IS NOT NULL ORDER BY version_number DESC LIMIT 1;
 INSERT INTO public.content_versions(version_id,version_number,status,created_by,created_at,published_at,change_summary)
 SELECT new_version,max(version_number)+1,'draft',NULL,now(),NULL,
 'Development scenario library: draft prices authorized November 9; CAC facts optional; unresolved statistics replaced with labeled authored context. Car scenarios remain disabled pending ownership mapping.' FROM public.content_versions;
 INSERT INTO public.jobs(job_id,version_id,soc_code,title,description,area_code,area_name,geography_level,wage_year,
 median_hourly_wage,hours_per_week,entry_education,related_experience,on_job_training,simulation_requirements,
 wage_source_url,requirements_source_url,reviewed_at,last_synced_at,is_approved,is_active,needs_english_skills,needs_computer_skills)
 SELECT md5(new_version::text||job_id::text)::uuid,new_version,soc_code,title,description,area_code,area_name,geography_level,wage_year,
 median_hourly_wage,hours_per_week,entry_education,related_experience,on_job_training,simulation_requirements,
 wage_source_url,requirements_source_url,reviewed_at,last_synced_at,is_approved,is_active,needs_english_skills,needs_computer_skills
 FROM public.jobs WHERE version_id=source_version;
 INSERT INTO public.personas(persona_id,name,description,general_starting_balance,weekly_income,version_id,starting_job_id,has_english_skills,has_computer_skills)
 SELECT md5(new_version::text||persona_id::text)::uuid,name,description,general_starting_balance,weekly_income,new_version,
 CASE WHEN starting_job_id IS NULL THEN NULL ELSE md5(new_version::text||starting_job_id::text)::uuid END,has_english_skills,has_computer_skills
 FROM public.personas WHERE version_id=source_version;
 FOR p IN SELECT * FROM public.personas WHERE version_id=new_version LOOP
  FOR c IN SELECT * FROM jsonb_array_elements(payload) LOOP
   IF c->>'intent' NOT IN ('ALL','EMPLOYED') AND upper(p.name)<>c->>'intent' THEN CONTINUE; END IF;
   sid:=md5(new_version::text||p.persona_id::text||(c->>'key'))::uuid;
   SELECT category_id INTO STRICT cat FROM public.categories WHERE name=c->>'category';
   INSERT INTO public.scenarios(scenario_id,version_id,title,description,category_id,persona_intent,schedule_type,default_day)
   VALUES(sid,new_version,c->>'title',c->>'description',cat,p.persona_id,
     CASE WHEN c->>'key'='D005' THEN 'scheduled' ELSE 'non_scheduled' END,
     CASE WHEN c->>'key'='D005' THEN 18 ELSE NULL END);
   INSERT INTO public.scenario_library_metadata(scenario_id,version_id,library_key,engine,requires_employment)
   VALUES(sid,new_version,c->>'key',c->>'engine',c->>'intent'='EMPLOYED' OR c->>'key'='D025');
   FOR ch IN SELECT * FROM jsonb_array_elements(c->'choices') LOOP
    new_choice:=md5(sid::text||(ch->>'key'))::uuid;
    INSERT INTO public.choices(choice_id,scenario_id,version_id,choice_text,balance_change,response_text,next_scenario_id,requires_cac,upfront_cost)
    VALUES(new_choice,sid,new_version,ch->>'text',(ch->>'amount')::numeric,ch->>'response',NULL,(ch->>'requires_cac')::boolean,(ch->>'upfront_cost')::numeric);
   END LOOP;
   FOR f IN SELECT * FROM jsonb_array_elements(c->'facts') LOOP
    INSERT INTO public.scenario_fact_copy(scenario_id,version_id,fact_role,semantic_key,display_text,source_url,copy_kind,verified,evidence)
    VALUES(sid,new_version,f->>'role',f->>'semantic_key',f->>'text',f->>'source_url',f->>'copy_kind',true,
     jsonb_build_object('library_key',c->>'key','development_edition',true,'source_hash','60a0e0557783c2c126662a0b3ba52f1dd85a0d12c54bf15f436b702cbdf8809a'));
   END LOOP;
   -- Essential monthly bills, with childcare/school bills only for Jordan.
   due:=CASE c->>'key' WHEN 'D006' THEN 6 WHEN 'D007' THEN 12 WHEN 'D008' THEN 27
     WHEN 'D009' THEN 16 WHEN 'D010' THEN 23 WHEN 'D013' THEN 8 WHEN 'D014' THEN 14 WHEN 'D018' THEN 29 ELSE NULL END;
   IF due IS NOT NULL THEN
    amount:=CASE c->>'key' WHEN 'D006' THEN CASE p.name WHEN 'Alex' THEN 693.50 WHEN 'Sofia' THEN 868.50 WHEN 'Jordan' THEN 1737 ELSE 1387 END
      WHEN 'D007' THEN 145 WHEN 'D008' THEN 68 WHEN 'D009' THEN 25 WHEN 'D010' THEN 65 WHEN 'D013' THEN 260 WHEN 'D014' THEN 31 WHEN 'D018' THEN 92 END;
    fee:=CASE c->>'key' WHEN 'D006' THEN 35 WHEN 'D007' THEN 10 WHEN 'D008' THEN 8 WHEN 'D009' THEN 5 WHEN 'D010' THEN 7 WHEN 'D013' THEN 25 WHEN 'D014' THEN 0 WHEN 'D018' THEN 9 END;
    eid:=md5(sid::text||'bill')::uuid;
    INSERT INTO public.persona_expenses(expense_id,persona_id,version_id,name,amount,first_due_day,repeat_interval_days,late_fee_amount)
    VALUES(eid,p.persona_id,new_version,c->>'title',amount,due,NULL,fee);
    INSERT INTO public.scenario_bill_links(expense_id,scenario_id,version_id) VALUES(eid,sid,new_version);
   END IF;
  END LOOP;
 END LOOP;
 -- Keep car-dependent cards in the catalog, disabled until ownership is configured.
 FOR c IN SELECT * FROM jsonb_array_elements(payload) WHERE value->>'intent'='CAR' LOOP
  sid:=md5(new_version::text||(c->>'key'))::uuid;
  SELECT category_id INTO STRICT cat FROM public.categories WHERE name=c->>'category';
  INSERT INTO public.scenarios(scenario_id,version_id,title,description,category_id,persona_intent,schedule_type,default_day)
  VALUES(sid,new_version,c->>'title',c->>'description',cat,NULL,'non_scheduled',NULL);
  INSERT INTO public.scenario_library_metadata(scenario_id,version_id,library_key,engine,enabled)
  VALUES(sid,new_version,c->>'key',c->>'engine',false);
  FOR ch IN SELECT * FROM jsonb_array_elements(c->'choices') LOOP
   INSERT INTO public.choices(choice_id,scenario_id,version_id,choice_text,balance_change,response_text,next_scenario_id,requires_cac,upfront_cost)
   VALUES(md5(sid::text||(ch->>'key'))::uuid,sid,new_version,ch->>'text',(ch->>'amount')::numeric,ch->>'response',NULL,(ch->>'requires_cac')::boolean,(ch->>'upfront_cost')::numeric);
  END LOOP;
  FOR f IN SELECT * FROM jsonb_array_elements(c->'facts') LOOP
   INSERT INTO public.scenario_fact_copy(scenario_id,version_id,fact_role,semantic_key,display_text,source_url,copy_kind,verified,evidence)
   VALUES(sid,new_version,f->>'role',f->>'semantic_key',f->>'text',f->>'source_url',f->>'copy_kind',true,jsonb_build_object('library_key',c->>'key','development_edition',true));
  END LOOP;
 END LOOP;
 IF (SELECT count(*) FROM public.personas WHERE version_id=new_version)<>4 OR
    (SELECT count(*) FROM public.jobs WHERE version_id=new_version AND is_active AND is_approved AND NOT needs_english_skills AND NOT needs_computer_skills)<2
 THEN RAISE EXCEPTION 'Incomplete playable edition'; END IF;
 IF EXISTS(SELECT 1 FROM public.personas pe WHERE pe.version_id=new_version AND NOT EXISTS(
  SELECT 1 FROM public.scenarios s JOIN public.scenario_library_metadata m USING(scenario_id,version_id)
  WHERE s.persona_intent=pe.persona_id AND m.library_key='D005' AND s.default_day=18)) THEN RAISE EXCEPTION 'Missing mandatory tax day'; END IF;
 UPDATE public.content_versions SET status='published',published_at=now() WHERE version_id=new_version;
END $install$;
COMMIT;
